14	/**
15	 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
16	 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
17	 * parseable entries or the requester IP can't be determined, so a bad value can
18	 * never lock every admin out — only an exact match is ever enforced.
19	 * Returns true when access should be REFUSED.
20	 */
21	async function adminIpBlocked(): Promise<boolean> {
22	  const raw = await getSetting("allowed_admin_ips", "");
23	  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
24	  if (entries.length === 0) return false; // no restriction configured
25	  const valid = entries.filter(isPlainIp);
26	  if (valid.length === 0) {
27	    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
28	    return false; // malformed -> fail open
29	  }
30	  const hdrs = await headers();
31	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim();
32	  if (!ip) {
33	    console.warn("[admin-ip] could not determine requester IP; failing open");
34	    return false;
35	  }
36	  return !valid.includes(ip);
37	}
