8	
9	/**
10	 * Staff-side live-chat actions. Every export gates on `requireArea("support")`
11	 * so only support staff / admins can read or write conversations. This file is
12	 * a "use server" module, so it may export **async functions only**.
13	 */
14	
15	/** Shape returned to the admin inbox client component. */
16	type InboxMessage = { id: string; sender: string; body: string; createdAt: string };
17	type InboxConversation = {
18	  id: string;
19	  visitorId: string;
20	  userId: string | null;
21	  name: string | null;
22	  email: string | null;
23	  status: string;
24	  assignedToId: string | null;
25	  unreadForAgent: boolean;
26	  lastMessageAt: string;
27	  createdAt: string;
28	  messages: InboxMessage[];
29	};
30	
31	/** List conversations for the inbox, unread + newest first. Polled by the client. */
32	export async function listConversations(): Promise<InboxConversation[]> {
33	  await requireArea("support");
34	  const rows = await db.chatConversation.findMany({
35	    orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
36	    take: 200,
37	    include: { messages: { orderBy: { createdAt: "asc" } } },
38	  });
39	  return rows.map((c) => ({
40	    id: c.id,
41	    visitorId: c.visitorId,
42	    userId: c.userId,
43	    name: c.name,
44	    email: c.email,
45	    status: c.status,
46	    assignedToId: c.assignedToId,
47	    unreadForAgent: c.unreadForAgent,
48	    lastMessageAt: c.lastMessageAt.toISOString(),
49	    createdAt: c.createdAt.toISOString(),
50	    messages: c.messages.map((m) => ({
51	      id: m.id,
52	      sender: m.sender,
53	      body: m.body,
54	      createdAt: m.createdAt.toISOString(),
55	    })),
56	  }));
57	}
