59	/** Fetch a single conversation's messages (used when opening / polling a thread). */
60	export async function getConversation(id: string): Promise<InboxConversation | null> {
61	  await requireArea("support");
62	  if (typeof id !== "string" || !id) return null;
63	  const c = await db.chatConversation.findUnique({
64	    where: { id },
65	    include: { messages: { orderBy: { createdAt: "asc" } } },
66	  });
67	  if (!c) return null;
68	  return {
69	    id: c.id,
70	    visitorId: c.visitorId,
71	    userId: c.userId,
72	    name: c.name,
73	    email: c.email,
74	    status: c.status,
75	    assignedToId: c.assignedToId,
76	    unreadForAgent: c.unreadForAgent,
77	    lastMessageAt: c.lastMessageAt.toISOString(),
78	    createdAt: c.createdAt.toISOString(),
79	    messages: c.messages.map((m) => ({
80	      id: m.id,
81	      sender: m.sender,
82	      body: m.body,
83	      createdAt: m.createdAt.toISOString(),
84	    })),
85	  };
86	}
