88	/**
89	 * Staff reply: append an "agent" message, flag the thread unread for the user,
90	 * clear the agent-unread flag, and assign it to the replying staff member.
91	 */
92	export async function replyToConversation(
93	  id: string,
94	  body: string
95	): Promise<{ error?: string; ok?: boolean }> {
96	  const staff = await requireArea("support");
97	
98	  const parsed = z
99	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
100	    .safeParse({ id, body });
101	  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };
102	
103	  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
104	  if (!convo) return { error: "Conversation not found." };
105	
106	  await db.$transaction([
107	    db.chatMessage.create({
108	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
109	    }),
110	    db.chatConversation.update({
111	      where: { id: parsed.data.id },
112	      data: {
113	        status: "OPEN",
114	        unreadForUser: true,
115	        unreadForAgent: false,
116	        assignedToId: staff.id,
117	        lastMessageAt: new Date(),
118	      },
119	    }),
120	  ]);
121	
122	  // If the visitor is a signed-in customer, drop them a notification.
123	  if (convo.userId) {
124	    await db.notification
125	      .create({
126	        data: {
127	          userId: convo.userId,
128	          title: "New reply in your live chat",
129	          href: "/dashboard",
130	        },
131	      })
132	      .catch(() => {});
133	  }
134	
135	  revalidatePath("/admin/chat");
136	  return { ok: true };
137	}
138	
139	/** Close a conversation (staff). */
140	export async function closeConversation(
141	  id: string
142	): Promise<{ error?: string; ok?: boolean }> {
143	  await requireArea("support");
144	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
145	  const convo = await db.chatConversation.findUnique({ where: { id } });
146	  if (!convo) return { error: "Conversation not found." };
147	  await db.chatConversation.update({
148	    where: { id },
149	    data: { status: "CLOSED", unreadForAgent: false },
150	  });
151	  revalidatePath("/admin/chat");
152	  return { ok: true };
153	}
154	
155	/** Assign a conversation to the acting staff member and mark it read for agents. */
156	export async function assignConversation(
157	  id: string
158	): Promise<{ error?: string; ok?: boolean }> {
159	  const staff = await requireArea("support");
160	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
161	  const convo = await db.chatConversation.findUnique({ where: { id } });
162	  if (!convo) return { error: "Conversation not found." };
163	  await db.chatConversation.update({
164	    where: { id },
165	    data: { assignedToId: staff.id, unreadForAgent: false },
166	  });
167	  revalidatePath("/admin/chat");
168	  return { ok: true };
169	}
